// Provided for labs 14.1 and 14.2. You do not edit this file (CUDA; also built for HIP and for
// both CPU emulators). Not in the book as code: ours.
//
// An in-place exclusive scan of unsigned ints, for any count. It is built the way section 11.9
// builds a global scan out of block scans, the three-kernel scan-scan-add of Fig. 11.14
// (pp. 273-274): every block scans one tile and writes the tile's total; the totals are scanned
// the same way (recursively, so any count works); a last kernel adds to every element the sum of
// the tiles before its own. No block ever waits for another block (no look-back), so the scan
// needs no forward-progress guarantee and has the same shape on CUDA, HIP and Metal
// (notes/today/ch14-facts.md C4).
//
//   int scanScratchCount(int count)
//       unsigned ints of scratch that launchExclusiveScan needs for `count` elements (at least 1).
//   void launchExclusiveScan(unsigned int* data, int count, unsigned int* scratch)
//       In place: data[0] = 0 and data[i] = (old) data[0] + ... + data[i-1]. count >= 1; the
//       sum of all `count` elements must fit in 32 bits. The last element's old value never
//       reaches any output, so a scan of n + 1 entries leaves the total of the first n in
//       data[n]. Launches: 1 when count <= 1024; 3 when count <= 1024 * 1024; 5 beyond that
//       (up to 2^30 elements); each extra level adds 2.
//
// Inside a block: a coalesced load of the tile into shared memory, a sequential scan of each
// thread's SCAN_ITEMS consecutive elements, a Kogge-Stone scan of the 256 thread totals (the
// double-buffered form of section 11.3, one barrier per step), and a coalesced store. Shared
// memory and barriers only: no warp intrinsics, so no lane masks to port to HIP.
#define SCAN_BLOCK_DIM 256
#define SCAN_ITEMS 4
#define SCAN_TILE (SCAN_BLOCK_DIM * SCAN_ITEMS)

// Scans each tile of SCAN_TILE elements in place. tileTotals may be null (a single tile).
__global__ void scanTileKernel(unsigned int* data, unsigned int count, unsigned int* tileTotals) {
    __shared__ unsigned int tile_s[SCAN_TILE];
    __shared__ unsigned int totals_s[2][SCAN_BLOCK_DIM];

    const unsigned int t = threadIdx.x;
    const unsigned int base = blockIdx.x * SCAN_TILE;

    // Coalesced load: on round k, thread t reads element k * SCAN_BLOCK_DIM + t of the tile.
    for (unsigned int k = 0; k < SCAN_ITEMS; ++k) {
        const unsigned int i = base + k * SCAN_BLOCK_DIM + t;
        tile_s[k * SCAN_BLOCK_DIM + t] = i < count ? data[i] : 0u;
    }
    __syncthreads();

    // Sequential exclusive scan of this thread's SCAN_ITEMS consecutive elements.
    unsigned int mine[SCAN_ITEMS];
    unsigned int threadTotal = 0;
    for (unsigned int k = 0; k < SCAN_ITEMS; ++k) {
        mine[k] = threadTotal;
        threadTotal += tile_s[t * SCAN_ITEMS + k];
    }

    // Kogge-Stone inclusive scan of the thread totals, double-buffered.
    unsigned int cur = 0;
    totals_s[cur][t] = threadTotal;
    __syncthreads();
    for (unsigned int stride = 1; stride < SCAN_BLOCK_DIM; stride *= 2) {
        unsigned int v = totals_s[cur][t];
        if (t >= stride) {
            v += totals_s[cur][t - stride];
        }
        totals_s[1 - cur][t] = v;
        cur = 1 - cur;
        __syncthreads();
    }
    const unsigned int inclusive = totals_s[cur][t];
    const unsigned int before = inclusive - threadTotal;   // totals of threads 0 .. t-1

    // Every thread read its own elements before the barriers above, so it may overwrite them.
    for (unsigned int k = 0; k < SCAN_ITEMS; ++k) {
        tile_s[t * SCAN_ITEMS + k] = mine[k] + before;
    }
    if (tileTotals != nullptr && t == SCAN_BLOCK_DIM - 1) {
        tileTotals[blockIdx.x] = inclusive;   // the last thread's inclusive total is the tile's
    }
    __syncthreads();

    for (unsigned int k = 0; k < SCAN_ITEMS; ++k) {
        const unsigned int i = base + k * SCAN_BLOCK_DIM + t;
        if (i < count) {
            data[i] = tile_s[k * SCAN_BLOCK_DIM + t];
        }
    }
}

// data[i] += tileOffsets[tile of i], for every element of every tile.
__global__ void addTileOffsetsKernel(unsigned int* data, unsigned int count, const unsigned int* tileOffsets) {
    const unsigned int add = tileOffsets[blockIdx.x];
    const unsigned int base = blockIdx.x * SCAN_TILE;
    for (unsigned int k = 0; k < SCAN_ITEMS; ++k) {
        const unsigned int i = base + k * SCAN_BLOCK_DIM + threadIdx.x;
        if (i < count) {
            data[i] += add;
        }
    }
}

static unsigned int scanTileCount(unsigned int count) { return (count + SCAN_TILE - 1) / SCAN_TILE; }
// Each level's totals start on a multiple of 4 elements (16 bytes), as the Metal twin needs.
static unsigned int scanRoundUp4(unsigned int x) { return (x + 3) / 4 * 4; }

int scanScratchCount(int count) {
    unsigned int c = count > 0 ? (unsigned int)count : 1u;
    unsigned int total = 0;
    while (c > SCAN_TILE) {
        c = scanTileCount(c);
        total += scanRoundUp4(c);
    }
    return total > 0 ? (int)total : 1;
}

void launchExclusiveScan(unsigned int* data, int count, unsigned int* scratch) {
    if (count <= 0) {
        return;
    }
    const unsigned int n = (unsigned int)count;
    const unsigned int tiles = scanTileCount(n);
    if (tiles == 1) {
        scanTileKernel<<<1, SCAN_BLOCK_DIM>>>(data, n, nullptr);
        return;
    }
    unsigned int* totals = scratch;                              // this level's tile totals
    scanTileKernel<<<tiles, SCAN_BLOCK_DIM>>>(data, n, totals);
    launchExclusiveScan(totals, (int)tiles, scratch + scanRoundUp4(tiles));   // totals -> offsets
    addTileOffsetsKernel<<<tiles, SCAN_BLOCK_DIM>>>(data, n, totals);
}
